def _components(grid, background):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and
                            (nx, ny) not in seen and grid[nx][ny] == color):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            result.append({
                'color': color, 'cells': cells, 'n': len(cells),
                'r0': min(rs), 'r1': max(rs), 'c0': min(cs), 'c1': max(cs),
                'cr': sum(rs) / len(rs), 'cc': sum(cs) / len(cs),
            })
    return result


def transform(grid):
    out = [row[:] for row in grid]
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    comps = _components(grid, background)
    if not comps:
        return out

    # The long bent component is the color key. Prefer broad, elongated components.
    key = max(comps, key=lambda x: (x['n'] * ((x['r1'] - x['r0'] + 1) + (x['c1'] - x['c0'] + 1)), x['n']))
    h, w = len(grid), len(grid[0])
    key_right = key['cc'] >= w / 2

    # A matching isolated stroke on the opposing side receives the key color.
    candidates = [x for x in comps if x is not key and
                  ((x['cc'] < w / 2) if key_right else (x['cc'] >= w / 2))]
    if not candidates:
        return out
    vertical_strokes = [x for x in candidates
                        if (x['c1'] - x['c0'] <= 1 and x['r1'] - x['r0'] >= 2)]
    if vertical_strokes:
        target = max(vertical_strokes, key=lambda x: (x['r1'] - x['r0'] + 1, -x['c0'], x['n']))
    else:
        target = max(candidates, key=lambda x: (x['n'], -x['cc']))
    for r, c in target['cells']:
        out[r][c] = key['color']
    return out


